create table brand_claim_verification_runs(id uuid not null,tenant_id uuid not null,answer_id uuid not null,brand_truth_card_id uuid not null,brand_truth_version integer not null,rules_version text not null check(rules_version='brand-claim-verification.v1'),input_sha256 char(64) not null,status text not null check(status='completed'),finding_count integer not null check(finding_count>=0),analyzed_at timestamptz not null,primary key(tenant_id,id),unique(tenant_id,input_sha256),foreign key(tenant_id,answer_id) references raw_answers(tenant_id,id),foreign key(tenant_id,brand_truth_card_id,brand_truth_version) references brand_truth_cards(tenant_id,id,version));
create table brand_claim_findings(id uuid not null,tenant_id uuid not null,run_id uuid not null,answer_id uuid not null,claim_text text not null,evidence_excerpt text not null,verdict text not null check(verdict in('fact_consistent','fact_conflict','self_reported_only','insufficient_evidence','not_applicable')),severity text not null check(severity in('info','warning','critical')),matched_rule text,brand_fact_id uuid,reason text not null,created_at timestamptz not null,primary key(tenant_id,id),foreign key(tenant_id,run_id) references brand_claim_verification_runs(tenant_id,id),foreign key(tenant_id,answer_id) references raw_answers(tenant_id,id));
do $$ declare n text;begin foreach n in array array['brand_claim_verification_runs','brand_claim_findings'] loop execute format('create trigger %I_append_only before update or delete on %I for each row execute function reject_immutable_mutation()',n,n);execute format('create trigger %I_no_truncate before truncate on %I for each statement execute function reject_immutable_mutation()',n,n);execute format('alter table %I enable row level security',n);execute format('alter table %I force row level security',n);execute format('create policy %I_tenant_isolation on %I using(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid) with check(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid)',n,n);end loop;end $$;
create index brand_claim_findings_verdict_idx on brand_claim_findings(tenant_id,verdict,created_at desc);
